/**
 * Preset Avatars Configuration
 * Clean Pixar-style child avatars without any circular borders or rings (Valid PNG)
 */

export const PRESET_AVATARS = [
  {
    id: 'boy_blue',
    label: 'Boy (Blue)',
    source: require('../assets/avatar_boy_blue.png'),
    dataUri: 'data:image/png;base64,',
  },
  {
    id: 'girl_pink',
    label: 'Girl (Pink)',
    source: require('../assets/avatar_girl_pink.png'),
    dataUri: 'data:image/png;base64,',
  },
  {
    id: 'boy_yellow',
    label: 'Boy (Yellow)',
    source: require('../assets/avatar_boy_yellow.png'),
    dataUri: 'data:image/png;base64,',
  },
  {
    id: 'girl_purple',
    label: 'Girl (Purple)',
    source: require('../assets/avatar_girl_purple.png'),
    dataUri: 'data:image/png;base64,',
  },
];

export const getAvatarUriById = (id) => {
  const avatar = PRESET_AVATARS.find((a) => a.id === id);
  return avatar ? avatar.dataUri : null;
};

export const getAvatarSourceById = (id) => {
  const avatar = PRESET_AVATARS.find((a) => a.id === id);
  return avatar ? avatar.source : null;
};
